import java.io.InputStream;
import java.io.OutputStream;
import java.io.IOException;

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private byte readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public boolean hasNext() {
            while (hasNextByte() && buffer[ptr] <= ' ') ptr++;
            return hasNextByte();
        }

        public char nextChar() {
            if (!hasNext()) return 0;
            return (char) readByte();
        }

        public int nextInt() {
            if (!hasNext()) return -1;
            int n = 0;
            byte b = readByte();
            while (b >= '0' && b <= '9') {
                n = n * 10 + (b - '0');
                b = readByte();
            }
            return n;
        }
    }

    static class FastOutput {
        private final OutputStream out;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;

        public FastOutput(OutputStream out) {
            this.out = out;
        }

        public void write(byte b) throws IOException {
            if (ptr == buffer.length) {
                flush();
            }
            buffer[ptr++] = b;
        }

        public void writeInt(long n) throws IOException {
            if (n == 0) {
                write((byte) '0');
                return;
            }
            byte[] temp = new byte[20];
            int len = 0;
            while (n > 0) {
                temp[len++] = (byte) ('0' + (n % 10));
                n /= 10;
            }
            for (int i = len - 1; i >= 0; i--) {
                write(temp[i]);
            }
        }

        public void flush() throws IOException {
            if (ptr > 0) {
                out.write(buffer, 0, ptr);
                ptr = 0;
            }
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner(System.in);
        FastOutput out = new FastOutput(System.out);

        int N = sc.nextInt();
        int M = sc.nextInt();
        int P = sc.nextInt();

        int[] row = new int[N + 1];
        for (int i = 1; i <= N; i++) {
            row[i] = i;
        }

        int[] col = new int[M + 1];
        for (int j = 1; j <= M; j++) {
            col[j] = j;
        }

        for (int k = 0; k < P; k++) {
            char type = sc.nextChar();
            int a = sc.nextInt();
            int b = sc.nextInt();

            if (type == 'L') {
                int temp = row[a];
                row[a] = row[b];
                row[b] = temp;
            } else {
                int temp = col[a];
                col[a] = col[b];
                col[b] = temp;
            }
        }

        long mVal = M;
        for (int i = 1; i <= N; i++) {
            long base = (long) (row[i] - 1) * mVal;
            for (int j = 1; j <= M; j++) {
                long val = base + col[j];
                out.writeInt(val);
                if (j < M) {
                    out.write((byte) ' ');
                } else {
                    out.write((byte) '\n');
                }
            }
        }

        out.flush();
    }
}
